Here is a C++ function that takes a reference to a `std::string` containing Markdown formatted text and returns a `std::string` containing HTML formatted text:
```cpp
#include <string>
#include <iostream>

std::string convert_markdown_to_html(std::string& markdown_text) {
  std::string html_text = "";
  // Loop through each line of markdown text
  std::string line;
  size_t i = 0;
  while (std::getline(std::stringstream(markdown_text), line, '\n')) {
    // Check if the line starts with a markdown syntax
    if (line[0] == '#' || line[0] == '*' || line[0] == '-') {
      std::string heading_prefix;
      while (line[0] == '#' || line[0] == '*' || line[0] == '-') {
        heading_prefix += line[0];
        line.erase(0, 1);
      }
      html_text += "<" + heading_prefix + ">" + line + "</" + heading_prefix + ">\n";
    } else if (line == "```" && (html_text.back() != '<' || html_text.back() != '>')) {
      // Check for code block syntax
      std::string language = "";
      while (line != "```" && (html_text.back() != '<' || html_text.back() != '>')) {
        if (line == "```javascript" || line == "```typescript" || line == "```html" || line == "```css") {
          language = "language-" + line.substr(4, line.length() - 4);
        }
        html_text += "<code " + language + ">";
        line.erase(0, 4);
      }
      html_text += line + "</code>\n";
    } else if (line[0] == '[' && line.find(']') != std::string::npos) {
      std::string url = line.substr(line.find(']') + 1);
      line.erase(0, line.find('[') + 1);
      line.erase(url.length());
      html_text += "<a href=\"" + url + "\">" + line + "</a>\n";
    } else if (line[0] == '!' && (html_text.back() != '<' || html_text.back() != '>')) {
      // Check for image syntax
      std::string image_path = line.substr(1);
      html_text += "<img src=\"" + image_path + "\">";
      line.erase(0, image_path.length());
    }
    // Add the line to the html text
    html_text += "<p>" + line + "</p>\n";
  }
  return html_text;
}
```

This function uses the `stringstream` class to read lines from the `std::string` and handle the different Markdown elements. It then converts them to HTML tags and adds them to the `std::string` `html_text`. The function handles headings, code blocks, links, images, and text paragraphs by appending appropriate HTML tags where necessary. Note that this function is a simple implementation and does not handle more complex Markdown elements or syntaxes like nested lists, table cells, or mathematical expressions. Additionally, it assumes that there are no extraneous or invalid Markdown syntaxes in the input.

